/**
 * Signals in message DRIVE_MOTOR_PWM.
 *
 * D-04 Stellgroesse links und rechts, ganzzahlig im Bereich -255 bis 255.
 *
 * All signal values are as on the CAN bus.
 */
struct amr_vehicle_drive_motor_pwm_t {
    /**
     * Range: -255..255 (-255..255 -)
     * Scale: 1
     * Offset: 0
     */
    int16_t motor_pwm_left;

    /**
     * Range: -255..255 (-255..255 -)
     * Scale: 1
     * Offset: 0
     */
    int16_t motor_pwm_right;
};

/**
 * Signals in message DRIVE_PATH_STATUS.
 *
 * D-05 Status des aktiven Fahrbefehlspfads. Macht die Arbitrierung von aussen beobachtbar und ist Nachweisgrundlage fuer das Failover.
 *
 * All signal values are as on the CAN bus.
 */
struct amr_vehicle_drive_path_status_t {
    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_active_source;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_operating_mode;

    /**
     * Range: 0..65535 (0..65535 ms)
     * Scale: 1
     * Offset: 0
     */
    uint16_t path_age_serial;

    /**
     * Range: 0..65535 (0..65535 ms)
     * Scale: 1
     * Offset: 0
     */
    uint16_t path_age_can;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_cliff_armed;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_cliff_timeout;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_estop_latched;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_vcu_hb_timeout;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_alive_counter;

    /**
     * CRC-8 nach SAE J1850 ueber Byte 0 bis 6 zuzueglich der Data-ID 0x30.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t path_crc8;
};

/**
 * Signals in message DRIVE_HEARTBEAT.
 *
 * D-06 Lebenszeichen des Fahrkerns. Die Bits drive_encoder_ok, drive_motor_ok und drive_core1_ok sind in der heutigen Firmware fest auf 1 gesetzt und fuehren noch keinen echten Zustand; die Behebung ist Bestandteil von K3.
 *
 * All signal values are as on the CAN bus.
 */
struct amr_vehicle_drive_heartbeat_t {
    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_encoder_ok;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_motor_ok;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_pid_active;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_bat_shutdown;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_core1_ok;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_failsafe_active;

    /**
     * Range: 0..255 (0..255 s)
     * Scale: 1
     * Offset: 0
     */
    uint8_t drive_uptime_mod256;
};

